#include <zephyr/drivers/nvmem.h>
#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/sys/__assert.h>

ssize_t nvmem_read(const struct nvmem_cell *cell, off_t offset,
		   void *data, size_t len)
{
	if (cell == NULL || data == NULL) {
		return -EINVAL;
	}

	if (offset < 0 || (size_t)offset > cell->size || ((size_t)offset + len) > cell->size) {
		return -EINVAL;
	}

	const struct device *dev = cell->nvmem;
	const struct nvmem_driver_api *api =
		(const struct nvmem_driver_api *)dev->api;

	if (api->read == NULL) {
		return -ENOTSUP;
	}

	return api->read(dev, cell->offset + offset, data, len);
}

ssize_t nvmem_write(const struct nvmem_cell *cell, off_t offset,
		    const void *data, size_t len)
{
	if (cell == NULL || data == NULL) {
		return -EINVAL;
	}

	if (offset < 0 || (size_t)offset > cell->size || ((size_t)offset + len) > cell->size) {
		return -EINVAL;
	}

	const struct device *dev = cell->nvmem;
	const struct nvmem_driver_api *api =
		(const struct nvmem_driver_api *)dev->api;

	if (api->write == NULL) {
		return -ENOTSUP;
	}

	return api->write(dev, cell->offset + offset, data, len);
}

ssize_t nvmem_erase(const struct nvmem_cell *cell)
{
	if (cell == NULL) {
		return -EINVAL;
	}

	const struct device *dev = cell->nvmem;
	const struct nvmem_driver_api *api =
		(const struct nvmem_driver_api *)dev->api;

	if (api->erase == NULL) {
		return -ENOTSUP;
	}

	return api->erase(dev, cell->offset, cell->size);
}

ssize_t nvmem_get_cell_info(const struct nvmem_cell *cell,
			    struct nvmem_cell_info *info)
{
	if (cell == NULL || info == NULL) {
		return -EINVAL;
	}

	info->offset = cell->offset;
	info->size = cell->size;

	return 0;
}

const struct nvmem_cell *nvmem_cell_get_by_name(const struct device *dev,
						const char *name)
{
	if (dev == NULL || name == NULL) {
		return NULL;
	}

	const struct nvmem_driver_api *api =
		(const struct nvmem_driver_api *)dev->api;

	if (api->get_cell_by_name == NULL) {
		return NULL;
	}

	return api->get_cell_by_name(dev, name);
}

